import subprocess, os, shutil
base="/tmp/ticonprobe"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base+"/probedir")
open(base+"/probefile","w").write("x")
def glyph_for(key):
    cfg=f"specs:\n  - pattern: \"^probedir$\"\n    icons: [\"{key}\"]\n"
    open(base+"/.pls.yml","w").write(cfg)
    r=subprocess.run(["/workspace/executable","-a=false"],cwd=base,capture_output=True,text=True)
    for line in r.stdout.splitlines():
        if "probedir" in line:
            # strip suffix /
            # format: <glyph><space>probedir/ or two spaces
            if line.startswith("  "):
                return ""  # empty glyph key exists (fallback dir would be folder, so this indicates existing empty)
            # glyph could be multi-char string before space
            return line.split(" probedir")[0]
    return None
def probe(keys):
    found={}
    for k in keys:
        g=glyph_for(k)
        # if g == folder icon and k!="dir" maybe fallback means absent - ambiguous if key glyph is folder too. Record.
        if g is not None and g!="" and g!="\uf07b":
            print(k, [hex(ord(c)) for c in g], repr(g)); found[k]=g
        elif g=="":
            print(k, "EMPTY"); found[k]=g
        elif g=="\uf07b":
            # could be fallback or dir key
            if k=="dir": print(k,"dir folder"); found[k]=g
            else: pass
    return found
PY
