import subprocess, os, shutil
def setup(kind):
    base="/tmp/tcfgedge"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base); open(base+"/file.txt","w").write("x")
    p=base+"/.pls.yml"
    if kind=="dir": os.makedirs(p)
    elif kind=="fifo": os.mkfifo(p)
    elif kind=="symlink_bad": os.symlink("missing.yml",p)
    elif kind=="symlink_good": open(base+"/real.yml","w").write("{}\n"); os.symlink("real.yml",p)
    elif kind=="symlink_badcontent": open(base+"/real.yml","w").write("x: [\n"); os.symlink("real.yml",p)
    elif kind=="unreadable": open(p,"w").write("{}\n"); os.chmod(p,0)
    elif kind=="execonly_dirparent": pass
    return base
for kind in ["dir","symlink_bad","symlink_good","symlink_badcontent","unreadable"]:
    base=setup(kind)
    r=subprocess.run(["/workspace/executable"],cwd=base,capture_output=True,text=True,timeout=5)
    print(kind, r.returncode, repr(r.stdout), repr(r.stderr))
    try: os.chmod(base+"/.pls.yml",0o644)
    except: pass
# fifo separately with timeout maybe would block opening? Use timeout 3 in subprocess.run and catch
base=setup("fifo")
try:
    r=subprocess.run(["/workspace/executable"],cwd=base,capture_output=True,text=True,timeout=3)
    print("fifo",repr(r.stdout))
except subprocess.TimeoutExpired as e:
    print("fifo timeout",e)
PY"}

