import sys, os, shutil, subprocess; sys.path.insert(0,"/tmp")
from runpty import run_pty
def grid(n, cols, down=False, namelen=5):
    d="/tmp/tgrid"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    for i in range(n):
        name=("f%0*d" % (namelen-1,i))[:namelen]
        open(os.path.join(d,name),"w").write("x")
    args=["-g=true","-i=false","-a=false","-l=false","-S=false","-s=name","-c=false"]
    if down: args.append("-D=true")
    out,st=run_pty(args,cwd=d,cols=cols,env_extra={"NO_COLOR":"1"})
    lines=out.decode().splitlines()
    # counts based on spaces
    counts=[len([x for x in l.split() if x]) for l in lines]
    print(f"n={n} cols={cols} down={down} maxw={namelen} rows={len(lines)} counts={counts} widths={[len(l) for l in lines]}")
for n in [1,2,3,5,10,14,15,16,20,24,25]:
    grid(n,120)
for cols in [20,21,34,35,36,70,71,80,100]:
    grid(20,cols)
for cols in [80,120]:
    for n in [14,15,16,20]: grid(n,cols,down=True)
