        spec(r"\.txt$", Some(&["text"]), None, None, None),
        spec(r"\.md$", Some(&["markdown"]), None, None, None),
        spec(r"\.rs$", Some(&["rust"]), Some("bright_red"), None, None),
        spec(r"\.sh$", Some(&["shell"]), None, None, None),
        spec(r"\.ini$", Some(&["config"]), None, None, None),
        spec(
