            None,
        ),
        spec(
            r"\.(avi|flv|mkv|mov|mp4|webm)$",
            Some(&["video"]),
            None,
            None,
            None,
        ),
        // Specific names.
        spec(
            r"^\.DS_Store$",
            Some(&["apple"]),
            None,
            Some(-2),
            None,
        ),
        spec(r"^\.env\b", Some(&["env"]), None, None, None),
        spec(r"^\.git$", Some(&["git"]), None, Some(-2), None),
        spec(r"^\.github$", Some(&["github"]), None, None, None),
        spec(r"^\.gitignore$", Some(&["git"]), None, None, None),
        spec(r"^\.pls\.yml$", Some(&["pls"]), None, Some(0), None),
        spec(
            r"^Cargo\.lock$",
            Some(&["lock"]),
