}

impl Default for Config {
    fn default() -> Self {
        Self {
            icons: default_icons(),
            specs: default_specs(),
        }
    }
}

// ---------------------------------------------------------------------------
// A small YAML value representation.
//
// serde_yaml is used for the actual YAML syntax.  Values are converted into
// this representation first so that configuration files can be merged in
// the same order (defaults, global file, local file) and with the same
// replacement/append behaviour as the reference program, and so that type
// errors can be reported in its format.

#[derive(Clone, Debug)]
enum YamlValue {
    Null,
    Bool(bool),
    Signed(i64),
    Unsigned(u64),
    Float(f64),
    String(String),
    Sequence(Vec<YamlValue>),
    Map(BTreeMap<String, YamlValue>),
}

struct YamlValueVisitor;

impl<'de> Visitor<'de> for YamlValueVisitor {
    type Value = YamlValue;

    fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("any YAML value")
    }

    fn visit_bool<E>(self, value: bool) -> Result<Self::Value, E> {
        Ok(YamlValue::Bool(value))
    }

    fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E> {
        Ok(YamlValue::Signed(value))
    }

    fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E> {
        Ok(YamlValue::Unsigned(value))
    }

    fn visit_f64<E>(self, value: f64) -> Result<Self::Value, E> {
        Ok(YamlValue::Float(value))
    }

    fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
    where
        E: de::Error,
    {
        Ok(YamlValue::String(value.to_owned()))
    }

    fn visit_string<E>(self, value: String) -> Result<Self::Value, E> {
        Ok(YamlValue::String(value))
    }

    fn visit_unit<E>(self) -> Result<Self::Value, E> {
        Ok(YamlValue::Null)
    }

    fn visit_none<E>(self) -> Result<Self::Value, E> {
        Ok(YamlValue::Null)
    }

    fn visit_some<D>(self, deserializer: D) -> Result<Self::Value, D::Error>
    where
        D: Deserializer<'de>,
    {
        YamlValue::deserialize(deserializer)
    }

    fn visit_seq<A>(self, mut seq: A) -> Result<Self::Value, A::Error>
    where
        A: SeqAccess<'de>,
    {
        let mut values = Vec::new();
        while let Some(value) = seq.next_element()? {
            values.push(value);
        }
        Ok(YamlValue::Sequence(values))
    }

    fn visit_map<A>(self, mut access: A) -> Result<Self::Value, A::Error>
    where
        A: MapAccess<'de>,
    {
        let mut map = BTreeMap::new();
        while let Some((key, value)) = access.next_entry::<String, YamlValue>()? {
            map.insert(key, value);
        }
        Ok(YamlValue::Map(map))
    }

    fn visit_enum<A>(self, data: A) -> Result<Self::Value, A::Error>
    where
        A: de::EnumAccess<'de>,
    {
        // serde_yaml presents an explicitly tagged value as an enum.
        // The configuration merger this mirrors turns such a value into a
        // one-entry map keyed by the tag.
        let (variant, access) = data.variant::<String>()?;
        let value = de::VariantAccess::newtype_variant(access)?;
        let mut map = BTreeMap::new();
        map.insert(variant, value);
        Ok(YamlValue::Map(map))
    }
}

impl<'de> Deserialize<'de> for YamlValue {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        deserializer.deserialize_any(YamlValueVisitor)
    }
}

#[derive(Clone, Debug)]
struct RootMap(BTreeMap<String, YamlValue>);

struct RootMapVisitor;

impl<'de> Visitor<'de> for RootMapVisitor {
    type Value = RootMap;

    fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("a map")
    }

    fn visit_map<A>(self, mut access: A) -> Result<Self::Value, A::Error>
    where
        A: MapAccess<'de>,
    {
        let mut map = BTreeMap::new();
        while let Some((key, value)) = access.next_entry::<String, YamlValue>()? {
            map.insert(key, value);
        }
        Ok(RootMap(map))
    }
}

impl<'de> Deserialize<'de> for RootMap {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        deserializer.deserialize_map(RootMapVisitor)
    }
}

#[derive(Clone)]
struct Source {
    display_path: String,
    root: BTreeMap<String, YamlValue>,
}

fn describe(value: &YamlValue) -> String {
    match value {
        YamlValue::Null => "unit".to_owned(),
        YamlValue::Bool(v) => format!("bool {v}"),
        YamlValue::Signed(v) => format!("signed int `{v}`"),
        YamlValue::Unsigned(v) => format!("unsigned int `{v}`"),
        YamlValue::Float(v) => format!("float `{v}`"),
        YamlValue::String(v) => format!("string {v:?}"),
        YamlValue::Sequence(_) => "sequence".to_owned(),
        YamlValue::Map(_) => "map".to_owned(),
    }
}

fn type_error(value: &YamlValue, expected: &str, key: &str, source: &Source) -> String {
    format!(
        "invalid type: found {}, expected {} for key \"{}\" in {} YAML file",
        describe(value),
        expected,
        key,
        source.display_path
    )
}

/// Make a config-file path suitable for error messages: lexical
/// components only (drop `.` components and duplicate separators), and an
/// absolute path expressed relative to the current directory.
fn display_config_path(path: &Path) -> String {
    let normalized: PathBuf = path.components().collect();
    if !normalized.is_absolute() {
        return normalized.to_string_lossy().into_owned();
    }
    let cwd = match std::env::current_dir() {
        Ok(cwd) => cwd,
        Err(_) => return normalized.to_string_lossy().into_owned(),
    };
    diff_paths(&normalized, &cwd)
        .to_string_lossy()
        .into_owned()
}

fn diff_paths(path: &Path, base: &Path) -> PathBuf {
    let path_components: Vec<Component<'_>> = path.components().collect();
    let base_components: Vec<Component<'_>> = base.components().collect();
    let mut common = 0;
    while common < path_components.len()
        && common < base_components.len()
        && path_components[common] == base_components[common]
    {
        common += 1;
    }
    // A root/prefix mismatch cannot be expressed relatively.
    for component in &path_components[..common] {
        if matches!(component, Component::RootDir | Component::Prefix(_)) {
            // Fine: the root was part of the common prefix.
        }
    }
    if common == 0 {
        return path.to_path_buf();
    }
    let mut result = PathBuf::new();
    for _ in common..base_components.len() {
        result.push("..");
    }
    for component in &path_components[common..] {
        result.push(component.as_os_str());
    }
    if result.as_os_str().is_empty() {
        result.push(".");
    }
    result
}

fn home_dir() -> Option<PathBuf> {
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home));
        }
    }
    // Fall back to the password database entry for the current user.
    unsafe {
        let uid = libc::getuid();
        let mut pw: libc::passwd = std::mem::zeroed();
        let mut buf = vec![0u8; 4096];
        let mut result: *mut libc::passwd = std::ptr::null_mut();
        let rc = libc::getpwuid_r(
            uid,
            &mut pw,
            buf.as_mut_ptr() as *mut libc::c_char,
            buf.len(),
            &mut result,
        );
        if rc == 0 && !result.is_null() && !pw.pw_dir.is_null() {
            let dir = std::ffi::CStr::from_ptr(pw.pw_dir)
                .to_string_lossy()
                .into_owned();
            if !dir.is_empty() {
                return Some(PathBuf::from(dir));
            }
        }
    }
    None
}

fn global_config_path() -> Option<PathBuf> {
    // `std::env::var` (rather than `var_os`) intentionally mirrors the
    // reference: a non-UTF-8 PLS_CONFIG is ignored, falling back to the
    // home-directory configuration.
    if let Ok(value) = std::env::var("PLS_CONFIG") {
        return Some(PathBuf::from(value));
    }
    home_dir().map(|home| home.join(".pls.yml"))
}

fn load_source(path: &Path) -> Result<Source, String> {
    let display_path = display_config_path(path);
    let text = std::fs::read_to_string(path)
        .map_err(|error| format!("{error} in {display_path} YAML file"))?;
    let root: RootMap = serde_yaml::from_str(&text)
        .map_err(|error| format!("{error} in {display_path} YAML file"))?;
    Ok(Source {
        display_path,
        root: root.0,
    })
}

// Values taken from a configuration file, tagged with the file they came
// from so error messages can name it.
#[derive(Clone)]
struct SourcedValue {
    value: YamlValue,
    source_index: usize, // usize::MAX for built-in defaults
}

enum MergedIcons {
    Map(BTreeMap<String, SourcedValue>),
    Other(SourcedValue),
}

enum SpecEntry {
    BuiltIn(Spec),
    FromFile(SourcedValue),
}

enum MergedSpecs {
    List(Vec<SpecEntry>),
    Other(SourcedValue),
}

pub fn load_config(local_dir: &Path) -> Result<Config, String> {
    let mut sources: Vec<Source> = Vec::new();
    if let Some(global_path) = global_config_path() {
        if global_path.is_file() {
            sources.push(load_source(&global_path)?);
        }
    }
    let local_path = local_dir.join(".pls.yml");
    if local_path.is_file() {
        sources.push(load_source(&local_path)?);
    }

    // Merge, in order: defaults, global, local.  Maps merge key by key,
    // sequences append and anything else is replaced by the later value.
    let mut merged_icons = MergedIcons::Map(
        default_icons()
            .into_iter()
            .map(|(key, value)| {
                (
                    key,
                    SourcedValue {
                        value: YamlValue::String(value),
                        source_index: usize::MAX,
                    },
                )
            })
            .collect(),
    );
    let mut merged_specs = MergedSpecs::List(
        default_specs()
            .into_iter()
            .map(SpecEntry::BuiltIn)
            .collect(),
    );

    for (source_index, source) in sources.iter().enumerate() {
        if let Some(value) = source.root.get("icons") {
            let sourced = SourcedValue {
                value: value.clone(),
                source_index,
            };
            merged_icons = match (merged_icons, value) {
                (MergedIcons::Map(mut entries), YamlValue::Map(new_entries)) => {
                    for (key, new_value) in new_entries {
                        entries.insert(
                            key.clone(),
                            SourcedValue {
                                value: new_value.clone(),
                                source_index,
                            },
                        );
                    }
                    MergedIcons::Map(entries)
                }
                (_, YamlValue::Map(new_entries)) => MergedIcons::Map(
                    new_entries
                        .iter()
                        .map(|(key, new_value)| {
                            (
                                key.clone(),
                                SourcedValue {
                                    value: new_value.clone(),
                                    source_index,
                                },
                            )
                        })
                        .collect(),
                ),
                _ => MergedIcons::Other(sourced),
            };
        }
        if let Some(value) = source.root.get("specs") {
            let sourced = SourcedValue {
                value: value.clone(),
                source_index,
            };
            merged_specs = match (merged_specs, value) {
                (MergedSpecs::List(mut entries), YamlValue::Sequence(new_entries)) => {
                    for entry in new_entries {
                        entries.push(SpecEntry::FromFile(SourcedValue {
                            value: entry.clone(),
                            source_index,
                        }));
                    }
                    MergedSpecs::List(entries)
                }
                (_, YamlValue::Sequence(new_entries)) => MergedSpecs::List(
                    new_entries
                        .iter()
                        .map(|entry| {
                            SpecEntry::FromFile(SourcedValue {
                                value: entry.clone(),
                                source_index,
                            })
                        })
                        .collect(),
                ),
                _ => MergedSpecs::Other(sourced),
            };
        }
    }

    let source_for = |sourced: &SourcedValue| -> Source {
        if sourced.source_index == usize::MAX {
            Source {
                display_path: String::new(),
                root: BTreeMap::new(),
            }
        } else {
            sources[sourced.source_index].clone()
        }
    };

    // Icons are extracted before specs.
    let icons: HashMap<String, String> = match &merged_icons {
        MergedIcons::Other(sourced) => {
            return Err(type_error(
                &sourced.value,
                "a map",
                "default.icons",
                &source_for(sourced),
            ));
        }
        MergedIcons::Map(entries) => {
            let mut icons = HashMap::new();
            for (key, sourced) in entries {
                match &sourced.value {
                    YamlValue::String(glyph) => {
                        icons.insert(key.clone(), glyph.clone());
                    }
                    other => {
                        return Err(type_error(
                            other,
                            "a string",
                            &format!("default.icons.{key}"),
                            &source_for(sourced),
                        ));
                    }
                }
            }
            icons
        }
    };

    let specs: Vec<Spec> = match &merged_specs {
        MergedSpecs::Other(sourced) => {
            return Err(type_error(
                &sourced.value,
                "a sequence",
                "default.specs",
                &source_for(sourced),
            ));
        }
        MergedSpecs::List(entries) => {
            let mut specs = Vec::new();
            for (index, entry) in entries.iter().enumerate() {
                match entry {
                    SpecEntry::BuiltIn(spec) => specs.push(spec.clone()),
                    SpecEntry::FromFile(sourced) => {
                        let source = source_for(sourced);
                        specs.push(extract_spec(&sourced.value, index, &source)?);
                    }
                }
            }
            specs
        }
    };

    Ok(Config { icons, specs })
}

fn extract_spec(value: &YamlValue, index: usize, source: &Source) -> Result<Spec, String> {
    let base_key = format!("default.specs.{index}");
    match value {
        YamlValue::Map(fields) => extract_spec_from_map(fields, &base_key, source),
        YamlValue::Sequence(items) => extract_spec_from_sequence(items, &base_key, source),
        other => Err(type_error(other, "struct Spec", &base_key, source)),
    }
}

fn make_spec(
    pattern: &YamlValue,
    icons: Option<&YamlValue>,
    style: Option<&YamlValue>,
    importance: Option<&YamlValue>,
    collapse: Option<&YamlValue>,
    base_key: &str,
    key_for: &dyn Fn(&str) -> String,
    source: &Source,
) -> Result<Spec, String> {
    // Fields are validated in alphabetic order of their field names when
    // they are supplied as a map, and in declaration order when supplied
    // as a sequence.  `make_spec` itself assumes the caller has already
    // run the per-field validators in the right order; see the callers.
    let _ = (icons, style, importance, collapse, base_key, key_for, source);
    let _ = pattern;
    unreachable!()
}

fn validate_pattern(
    value: &YamlValue,
    key: &str,
    source: &Source,
) -> Result<Regex, String> {
    match value {
        YamlValue::String(pattern) => Regex::new(pattern).map_err(|error| {
            format!("{error} for key \"{key}\" in {} YAML file", source.display_path)
        }),
        other => Err(type_error(other, "a string", key, source)),
    }
}

fn validate_icons(
    value: Option<&YamlValue>,
    key: &str,
    source: &Source,
) -> Result<Option<Vec<String>>, String> {
    match value {
        None | Some(YamlValue::Null) => Ok(None),
        Some(YamlValue::Sequence(items)) => {
            let mut icons = Vec::new();
            for (index, item) in items.iter().enumerate() {
                match item {
                    YamlValue::String(icon) => icons.push(icon.clone()),
                    other => {
                        return Err(type_error(
                            other,
                            "a string",
                            &format!("{key}.{index}"),
                            source,
                        ))
                    }
                }
            }
            Ok(Some(icons))
        }
        Some(other) => Err(type_error(other, "a sequence", key, source)),
    }
}

fn validate_style(
    value: Option<&YamlValue>,
    key: &str,
    source: &Source,
) -> Result<Option<String>, String> {
    match value {
        None | Some(YamlValue::Null) => Ok(None),
        Some(YamlValue::String(style)) => Ok(Some(style.clone())),
        Some(other) => Err(type_error(other, "a string", key, source)),
    }
}

fn validate_importance(
    value: Option<&YamlValue>,
    key: &str,
    source: &Source,
) -> Result<Option<i8>, String> {
    match value {
        None | Some(YamlValue::Null) => Ok(None),
        Some(YamlValue::Signed(v)) => {
            if (-128..=127).contains(v) {
                Ok(Some(*v as i8))
            } else {
                Err(format!(
                    "invalid value {}, expected i8 for key \"{}\" in {} YAML file",
                    describe(&YamlValue::Signed(*v)),
                    key,
                    source.display_path
                ))
            }
        }
        Some(YamlValue::Unsigned(v)) => {
            if *v <= 127 {
                Ok(Some(*v as i8))
            } else {
                Err(format!(
                    "invalid value {}, expected i8 for key \"{}\" in {} YAML file",
                    describe(&YamlValue::Unsigned(*v)),
                    key,
                    source.display_path
                ))
            }
        }
        Some(other) => Err(type_error(other, "i8", key, source)),
    }
}

fn validate_collapse(
    value: Option<&YamlValue>,
    key: &str,
    source: &Source,
) -> Result<Option<Collapse>, String> {
    match value {
        None | Some(YamlValue::Null) => Ok(None),
        Some(YamlValue::String(variant)) => {
            if variant == "name" || variant == "ext" {
                Err(format!(
                    "invalid type: found unit variant, expected newtype variant for key \"{}\" in {} YAML file",
                    key, source.display_path
                ))
            } else {
                Err(format!(
                    "unknown variant: found `{variant}`, expected ``name` or `ext`` for key \"{}\" in {} YAML file",
                    key, source.display_path
                ))
            }
        }
        Some(YamlValue::Map(entries)) => {
            let Some((variant, variant_value)) = entries.iter().next() else {
                return Err(type_error(
                    &YamlValue::Map(entries.clone()),
                    "enum",
                    key,
                    source,
                ));
            };
            let variant_key = format!("{key}.{variant}");
            match variant.as_str() {
                "name" | "ext" => match variant_value {
                    YamlValue::String(target) => Ok(Some(if variant == "name" {
                        Collapse::Name(target.clone())
                    } else {
                        Collapse::Ext(target.clone())
                    })),
                    other => Err(type_error(other, "a string", &variant_key, source)),
                },
                _ => Err(format!(
                    "unknown variant: found `{variant}`, expected ``name` or `ext`` for key \"{}\" in {} YAML file",
                    variant_key, source.display_path
                )),
            }
        }
        Some(other) => Err(type_error(other, "enum Collapse", key, source)),
    }
}

fn extract_spec_from_map(
    fields: &BTreeMap<String, YamlValue>,
    base_key: &str,
    source: &Source,
) -> Result<Spec, String> {
    // BTreeMap iteration is alphabetic, which is also the order in which
    // field errors are reported by the reference program.
    let mut pattern: Option<Regex> = None;
    let mut icons: Option<Vec<String>> = None;
    let mut style: Option<String> = None;
    let mut importance: Option<i8> = None;
    let mut collapse: Option<Collapse> = None;

    for (field, value) in fields {
        let key = format!("{base_key}.{field}");
        match field.as_str() {
            "collapse" => collapse = validate_collapse(Some(value), &key, source)?,
            "icons" => icons = validate_icons(Some(value), &key, source)?,
            "importance" => importance = validate_importance(Some(value), &key, source)?,
            "pattern" => pattern = Some(validate_pattern(value, &key, source)?),
            "style" => style = validate_style(Some(value), &key, source)?,
            _ => {}
        }
    }

    let Some(pattern) = pattern else {
        return Err(format!(
            "missing field `pattern` for key \"{}\" in {} YAML file",
            base_key, source.display_path
        ));
    };
    Ok(Spec {
        pattern,
        icons,
        style,
        importance,
        collapse,
    })
}

fn extract_spec_from_sequence(
    items: &[YamlValue],
    base_key: &str,
    source: &Source,
) -> Result<Spec, String> {
    // A spec written as a sequence is in declaration order:
    // pattern, icons, style, importance, collapse.  Extra items are
    // ignored; too few are reported only after the present items have
    // themselves been validated.
    let mut next = |index: usize| -> Result<&YamlValue, String> {
        items.get(index).ok_or_else(|| {
            format!(
                "invalid length {}, expected struct Spec with 5 elements for key \"{}\" in {} YAML file",
                items.len(),
                base_key,
                source.display_path
            )
        })
    };
    let pattern = validate_pattern(next(0)?, &format!("{base_key}.0"), source)?;
    let icons = validate_icons(Some(next(1)?), &format!("{base_key}.1"), source)?;
    let style = validate_style(Some(next(2)?), &format!("{base_key}.2"), source)?;
    let importance = validate_importance(Some(next(3)?), &format!("{base_key}.3"), source)?;
    let collapse = validate_collapse(Some(next(4)?), &format!("{base_key}.4"), source)?;
    Ok(Spec {
        pattern,
        icons,
        style,
        importance,
        collapse,
    })
}
RS"}

