use colored::{Color, ColoredString, Colorize};
use unicode_width::UnicodeWidthStr;

/// One piece of a rendered line: the plain text (used for measuring) and
/// the text as it should actually be printed (which may contain ANSI
/// escape sequences).
#[derive(Clone, Debug)]
pub struct Seg {
    pub plain: String,
    pub rendered: String,
}

impl Seg {
    pub fn plain(text: impl Into<String>) -> Self {
        let text = text.into();
        Self {
            rendered: text.clone(),
            plain: text,
        }
    }

    pub fn colored(text: impl Into<String>, colored: ColoredString) -> Self {
        Self {
            plain: text.into(),
            rendered: colored.to_string(),
        }
    }

    pub fn width(&self) -> usize {
        UnicodeWidthStr::width(self.plain.as_str())
    }
}

/// Apply a list of style words (as found in a spec's `style` string,
/// split on whitespace) to a piece of text.
pub fn styled(text: impl Into<String>, style_words: &[String]) -> Seg {
    let text = text.into();
    if style_words.iter().any(|word| word == "hidden") {
        return Seg {
            plain: String::new(),
            rendered: String::new(),
        };
    }
    let mut colored = text.as_str().clear();
    for word in style_words {
        colored = apply_word(colored, word);
    }
    Seg::colored(text, colored)
}

fn apply_word(colored: ColoredString, word: &str) -> ColoredString {
    match word {
        "bold" => colored.bold(),
        "dimmed" => colored.dimmed(),
        "italic" => colored.italic(),
        "underline" => colored.underline(),
        "blink" => colored.blink(),
        "reversed" => colored.reversed(),
        "strikethrough" => colored.strikethrough(),
        "clear" => colored.clear(),
        _ => match word.parse::<Color>() {
            Ok(color) => colored.color(color),
            Err(_) => colored,
        },
    }
}

pub fn style_words(style: &str) -> Vec<String> {
    style.split_whitespace().map(str::to_owned).collect()
}

/// The bold-red "error:" introduction used by all top-level errors.
pub fn error_line(message: &str) -> String {
    format!("{} {}", "error:".bold().red(), message)
}
RS"}

