{"command":"cat > src/node.rs <<'RS'
use crate::config::{load_config, Collapse, Config};
use crate::style::style_words;
use std::ffi::OsStr;
use std::fs::{self, Metadata};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::{FileTypeExt, MetadataExt};
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::time::{Duration, SystemTime};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NodeType {
    Dir,
    Symlink,
    Fifo,
    Socket,
    BlockDevice,
    CharDevice,
    File,
}

impl NodeType {
    pub fn from_file_type(file_type: fs::FileType) -> Self {
        if file_type.is_dir() {
            Self::Dir
        } else if file_type.is_symlink() {
            Self::Symlink
        } else if file_type.is_fifo() {
            Self::Fifo
        } else if file_type.is_socket() {
            Self::Socket
        } else if file_type.is_block_device() {
            Self::BlockDevice
        } else if file_type.is_char_device() {
            Self::CharDevice
        } else {
            Self::File
        }
    }

    pub fn sort_rank(self) -> u8 {
        match self {
            Self::Dir => 0,
            Self::Symlink => 1,
            Self::Fifo => 2,
            Self::Socket => 3,
            Self::BlockDevice => 4,
            Self::CharDevice => 5,
            Self::File => 6,
        }
    }

    pub fn typ_char(self) -> char {
        match self {
            Self::Dir => 'd',
            Self::Symlink => 'l',
            Self::Fifo => 'p',
            Self::Socket => 's',
            Self::BlockDevice => 'b',
            Self::CharDevice => 'c',
            Self::File => 'f',
        }
    }

    pub fn suffix(self) -> &'static str {
        match self {
            Self::Dir => "/",
            Self::Symlink => "@",
            Self::Fifo => "|",
            Self::Socket => "=",
            _ => "",
        }
    }

    pub fn icon_key(self) -> &'static str {
        match self {
            Self::Dir => "dir",
            Self::Symlink => "symlink",
            Self::Fifo => "fifo",
            Self::Socket => "socket",
            Self::BlockDevice => "block_device",
            Self::CharDevice => "char_device",
            Self::File => "file",
        }
    }

    pub fn filter_name(self) -> &'static str {
        match self {
            Self::Dir => "dir",
            Self::Symlink => "symlink",
            Self::Fifo => "fifo",
            Self::Socket => "socket",
            Self::BlockDevice => "block-device",
            Self::CharDevice => "char-device",
            Self::File => "file",
        }
    }
}

pub struct Node {
    pub path: PathBuf,
    /// The file name, used for classification, filtering and sorting, and
    /// as the displayed name of a node found inside a listed directory.
    pub name: String,
    pub name_bytes: Vec<u8>,
    /// The name as displayed for a node named explicitly on the command
    /// line (its full, as-given path).
    pub display_name: String,
    pub metadata: Metadata,
    pub typ: NodeType,
    pub config: Rc<Config>,
    pub icon: String,
    pub style: Vec<String>,
    pub importance: i8,
    pub collapse: Option<Collapse>,
    pub user: String,
    pub group: String,
}

fn file_name_of(path: &Path) -> (String, Vec<u8>) {
    if let Some(name) = path.file_name() {
        (
            name.to_string_lossy().into_owned(),
            name.as_bytes().to_vec(),
        )
    } else {
        (
            path.to_string_lossy().into_owned(),
            path.as_os_str().as_bytes().to_vec(),
        )
    }
}

fn lookup_user(uid: u32) -> String {
    unsafe {
        let pw = libc::getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_name.is_null() {
            return std::ffi::CStr::from_ptr((*pw).pw_name)
                .to_string_lossy()
                .into_owned();
        }
    }
    uid.to_string()
}

fn lookup_group(gid: u32) -> String {
    unsafe {
        let gr = libc::getgrgid(gid);
        if !gr.is_null() && !(*gr).gr_name.is_null() {
            return std::ffi::CStr::from_ptr((*gr).gr_name)
                .to_string_lossy()
                .into_owned();
        }
    }
    gid.to_string()
}

fn build(
    path: PathBuf,
    metadata: Metadata,
    config: Rc<Config>,
    explicit: bool,
) -> Node {
    let typ = NodeType::from_file_type(metadata.file_type());
    let (name, name_bytes) = file_name_of(&path);
    let display_name = if explicit {
        path.to_string_lossy().into_owned()
    } else {
        name.clone()
    };

    let mut icon = config
        .icons
        .get(typ.icon_key())
        .cloned()
        .unwrap_or_default();
    let mut style: Vec<String> = if typ == NodeType::Dir {
        vec!["blue".to_owned()]
    } else {
        Vec::new()
    };
    let mut importance: i8 = if name.starts_with('.') { -1 } else { 0 };
    let mut collapse: Option<Collapse> = None;

    for spec in &config.specs {
        if !spec.pattern.is_match(&name) {
            continue;
        }
        if let Some(candidates) = &spec.icons {
            if let Some(glyph) = candidates
                .iter()
                .find_map(|candidate| config.icons.get(candidate))
            {
                icon = glyph.clone();
            }
        }
        if let Some(spec_style) = &spec.style {
            style.extend(style_words(spec_style));
        }
        if let Some(spec_importance) = spec.importance {
            importance = spec_importance;
        }
        if let Some(spec_collapse) = &spec.collapse {
            collapse = Some(spec_collapse.clone());
        }
    }

    let user = lookup_user(metadata.uid());
    let group = lookup_group(metadata.gid());

    Node {
        path,
        name,
        name_bytes,
        display_name,
        metadata,
        typ,
        config,
        icon,
        style,
        importance,
        collapse,
        user,
        group,
    }
}

/// Create a node for a path given on the command line.  Such a node
/// loads the configuration belonging to its own directory: the
/// directory itself for a directory, its parent otherwise.
pub fn create_root_node(path: PathBuf) -> Result<Node, String> {
    let metadata = fs::symlink_metadata(&path).map_err(|error| error.to_string())?;
    let typ = NodeType::from_file_type(metadata.file_type());
    let config_dir = if typ == NodeType::Dir {
        path.clone()
    } else {
        path.parent()
            .map(Path::to_path_buf)
            .unwrap_or_default()
    };
    let config = Rc::new(load_config(&config_dir)?);
    Ok(build(path, metadata, config, true))
}

/// Create a node for an entry of a listed directory, using that
/// directory's already-loaded configuration.
pub fn create_child_node(path: PathBuf, config: &Rc<Config>) -> Option<Node> {
    let metadata = fs::symlink_metadata(&path).ok()?;
    Some(build(path, metadata, Rc::clone(config), false))
}

impl Node {
    pub fn dev(&self) -> u64 {
        self.metadata.dev()
    }
    pub fn ino(&self) -> u64 {
        self.metadata.ino()
    }
    pub fn nlink(&self) -> u64 {
        self.metadata.nlink()
    }
    pub fn mode(&self) -> u32 {
        self.metadata.mode()
    }
    pub fn uid(&self) -> u32 {
        self.metadata.uid()
    }
    pub fn gid(&self) -> u32 {
        self.metadata.gid()
    }
    pub fn size(&self) -> u64 {
        self.metadata.len()
    }
    pub fn blocks(&self) -> u64 {
        self.metadata.blocks()
    }
    pub fn btime(&self) -> Option<SystemTime> {
        self.metadata.created().ok()
    }
    pub fn ctime(&self) -> Option<SystemTime> {
        let sec = self.metadata.ctime();
        let nsec = self.metadata.ctime_nsec();
        Some(system_time_from_unix(sec, nsec))
    }
    pub fn mtime(&self) -> Option<SystemTime> {
        self.metadata.modified().ok()
    }
    pub fn atime(&self) -> Option<SystemTime> {
        self.metadata.accessed().ok()
    }

    pub fn canonical_name(&self) -> String {
        self.name
            .trim_start_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase()
    }

    pub fn extension(&self) -> String {
        Path::new(&self.name)
            .extension()
            .map(|ext: &OsStr| ext.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    pub fn importance_difference(&self, cutoff: i8) -> i8 {
        self.importance.wrapping_sub(cutoff)
    }
}

fn system_time_from_unix(sec: i64, nsec: i64) -> SystemTime {
    // `nsec` is the nanosecond part of a C `timespec`, which is always
    // normalised to 0..1_000_000_000 even for negative times.
    if sec >= 0 {
        SystemTime::UNIX_EPOCH + Duration::new(sec as u64, nsec.clamp(0, 999_999_999) as u32)
    } else if nsec == 0 {
        SystemTime::UNIX_EPOCH - Duration::new((-sec) as u64, 0)
    } else {
        SystemTime::UNIX_EPOCH
            - Duration::new(
                (-sec - 1) as u64,
                (1_000_000_000 - nsec.clamp(0, 999_999_999)) as u32,
            )
    }
}
RS"}

