        } else if file_type.is_fifo() {
            Self::Fifo
        } else if file_type.is_socket() {
            Self::Socket
        } else if file_type.is_block_device() {
            Self::BlockDevice
        } else if file_type.is_char_device() {
            Self::CharDevice
        } else {
            Self::File
        }
    }

    pub fn sort_rank(self) -> u8 {
        match self {
            Self::Dir => 0,
            Self::Symlink => 1,
            Self::Fifo => 2,
            Self::Socket => 3,
            Self::BlockDevice => 4,
            Self::CharDevice => 5,
            Self::File => 6,
