}

fn build(
    path: PathBuf,
    metadata: Metadata,
    config: Rc<Config>,
    explicit: bool,
) -> Node {
    let typ = NodeType::from_file_type(metadata.file_type());
    let (name, name_bytes) = file_name_of(&path);
    let display_name = if explicit {
        path.to_string_lossy().into_owned()
    } else {
        name.clone()
    };

    let mut icon = config
        .icons
        .get(typ.icon_key())
        .cloned()
        .unwrap_or_default();
    let mut style: Vec<String> = if typ == NodeType::Dir {
        vec!["blue".to_owned()]
    } else {
        Vec::new()
    };
    let mut importance: i8 = if name.starts_with('.') { -1 } else { 0 };
    let mut collapse: Option<Collapse> = None;

    for spec in &config.specs {
        if !spec.pattern.is_match(&name) {
            continue;
        }
        if let Some(candidates) = &spec.icons {
            if let Some(glyph) = candidates
                .iter()
                .find_map(|candidate| config.icons.get(candidate))
            {
                icon = glyph.clone();
            }
        }
        if let Some(spec_style) = &spec.style {
            style.extend(style_words(spec_style));
        }
        if let Some(spec_importance) = spec.importance {
            importance = spec_importance;
        }
        if let Some(spec_collapse) = &spec.collapse {
            collapse = Some(spec_collapse.clone());
        }
    }

    let user = lookup_user(metadata.uid());
    let group = lookup_group(metadata.gid());

    Node {
        path,
        name,
        name_bytes,
        display_name,
        metadata,
        typ,
        config,
        icon,
        style,
        importance,
        collapse,
        user,
        group,
    }
