/// Create a node for a path given on the command line.  Such a node
/// loads the configuration belonging to its own directory: the
/// directory itself for a directory, its parent otherwise.
pub fn create_root_node(path: PathBuf) -> Result<Node, String> {
    let metadata = fs::symlink_metadata(&path).map_err(|error| error.to_string())?;
    let typ = NodeType::from_file_type(metadata.file_type());
    let config_dir = if typ == NodeType::Dir {
        path.clone()
    } else {
        path.parent()
            .map(Path::to_path_buf)
            .unwrap_or_default()
    };
    let config = Rc::new(load_config(&config_dir)?);
    Ok(build(path, metadata, config, true))
}

/// Create a node for an entry of a listed directory, using that
/// directory's already-loaded configuration.
pub fn create_child_node(path: PathBuf, config: &Rc<Config>) -> Option<Node> {
    let metadata = fs::symlink_metadata(&path).ok()?;
    Some(build(path, metadata, Rc::clone(config), false))
}

impl Node {
    pub fn dev(&self) -> u64 {
        self.metadata.dev()
    }
    pub fn ino(&self) -> u64 {
        self.metadata.ino()
    }
    pub fn nlink(&self) -> u64 {
        self.metadata.nlink()
    }
    pub fn mode(&self) -> u32 {
        self.metadata.mode()
    }
    pub fn uid(&self) -> u32 {
        self.metadata.uid()
    }
    pub fn gid(&self) -> u32 {
        self.metadata.gid()
    }
    pub fn size(&self) -> u64 {
        self.metadata.len()
    }
    pub fn blocks(&self) -> u64 {
        self.metadata.blocks()
    }
    pub fn btime(&self) -> Option<SystemTime> {
        self.metadata.created().ok()
    }
    pub fn ctime(&self) -> Option<SystemTime> {
        let sec = self.metadata.ctime();
        let nsec = self.metadata.ctime_nsec();
        Some(system_time_from_unix(sec, nsec))
    }
    pub fn mtime(&self) -> Option<SystemTime> {
        self.metadata.modified().ok()
    }
    pub fn atime(&self) -> Option<SystemTime> {
        self.metadata.accessed().ok()
    }

    pub fn canonical_name(&self) -> String {
        self.name
            .trim_start_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase()
    }

    pub fn extension(&self) -> String {
        Path::new(&self.name)
            .extension()
            .map(|ext: &OsStr| ext.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    pub fn importance_difference(&self, cutoff: i8) -> i8 {
        self.importance.wrapping_sub(cutoff)
    }
}

fn system_time_from_unix(sec: i64, nsec: i64) -> SystemTime {
    // `nsec` is the nanosecond part of a C `timespec`, which is always
    // normalised to 0..1_000_000_000 even for negative times.
    if sec >= 0 {
        SystemTime::UNIX_EPOCH + Duration::new(sec as u64, nsec.clamp(0, 999_999_999) as u32)
    } else if nsec == 0 {
        SystemTime::UNIX_EPOCH - Duration::new((-sec) as u64, 0)
    } else {
        SystemTime::UNIX_EPOCH
            - Duration::new(
                (-sec - 1) as u64,
                (1_000_000_000 - nsec.clamp(0, 999_999_999)) as u32,
            )
    }
}
