}

fn get_bool(matches: &clap::ArgMatches, name: &str) -> bool {
    matches
        .get_one::<String>(name)
        .map(|value| value == "true")
        .unwrap_or(false)
}

fn expand_details(values: &[String]) -> Vec<Detail> {
    fn single(name: &str) -> Option<Detail> {
        Some(match name {
            "dev" => Detail::Dev,
            "ino" => Detail::Ino,
            "nlink" => Detail::Nlink,
            "typ" => Detail::Typ,
            "perm" => Detail::Perm,
            "oct" => Detail::Oct,
            "user" => Detail::User,
            "uid" => Detail::Uid,
            "group" => Detail::Group,
            "gid" => Detail::Gid,
            "size" => Detail::Size,
            "blocks" => Detail::Blocks,
            "btime" => Detail::Btime,
            "ctime" => Detail::Ctime,
            "mtime" => Detail::Mtime,
            "atime" => Detail::Atime,
            "git" => Detail::Git,
            _ => return None,
        })
    }
    const STD: &[Detail] = &[
        Detail::Nlink,
        Detail::Typ,
        Detail::Perm,
        Detail::User,
        Detail::Group,
        Detail::Size,
        Detail::Mtime,
    ];
    const ALL: &[Detail] = &[
        Detail::Dev,
        Detail::Ino,
        Detail::Nlink,
        Detail::Typ,
        Detail::Perm,
        Detail::Oct,
        Detail::User,
        Detail::Uid,
        Detail::Group,
        Detail::Gid,
        Detail::Size,
        Detail::Blocks,
        Detail::Btime,
        Detail::Ctime,
        Detail::Mtime,
        Detail::Atime,
        Detail::Git,
    ];
    let mut result: Vec<Detail> = Vec::new();
    let mut push = |detail: Detail, result: &mut Vec<Detail>| {
        if let Some(position) = result.iter().position(|d| *d == detail) {
            result.remove(position);
        }
        result.push(detail);
    };
    for value in values {
        match value.as_str() {
            "none" => result.clear(),
            "std" => {
                for detail in STD {
                    push(*detail, &mut result);
                }
            }
            "all" => {
                for detail in ALL {
                    push(*detail, &mut result);
                }
            }
            other => {
                if let Some(detail) = single(other) {
                    push(detail, &mut result);
                }
            }
        }
    }
    result
}

fn expand_types(values: &[String]) -> Vec<String> {
    const ALL: &[&str] = &[
        "dir",
        "symlink",
        "fifo",
        "socket",
        "block-device",
        "char-device",
        "file",
    ];
    let mut result: Vec<String> = Vec::new();
    for value in values {
        match value.as_str() {
            "none" => result.clear(),
            "all" => {
                for typ in ALL {
                    if !result.iter().any(|existing| existing == typ) {
                        result.push((*typ).to_owned());
                    }
                }
            }
            other => {
                if !result.iter().any(|existing| existing == other) {
                    result.push(other.to_owned());
                }
            }
        }
    }
    result
}

fn expand_sort(values: &[String]) -> Vec<SortBase> {
    fn base_for(value: &str) -> Option<SortBase> {
        use SortField::*;
        Some(match value {
            "dev" => SortBase::Forward(Dev),
            "ino" => SortBase::Forward(Ino),
            "nlink" => SortBase::Forward(Nlink),
            "typ" => SortBase::Forward(Typ),
            "cat" => SortBase::Forward(Cat),
            "user" => SortBase::Forward(User),
            "uid" => SortBase::Forward(Uid),
            "group" => SortBase::Forward(Group),
            "gid" => SortBase::Forward(Gid),
            "size" => SortBase::Forward(Size),
            "blocks" => SortBase::Forward(Blocks),
            "btime" => SortBase::Forward(Btime),
            "ctime" => SortBase::Forward(Ctime),
            "mtime" => SortBase::Forward(Mtime),
            "atime" => SortBase::Forward(Atime),
            "name" => SortBase::Forward(Name),
            "cname" => SortBase::Forward(Cname),
            "ext" => SortBase::Forward(Ext),
            "inode_" => SortBase::InodeReversed,
            "nlinks_" => SortBase::NlinksReversed,
            "typ_" => SortBase::Reversed(Typ),
            "cat_" => SortBase::Reversed(Cat),
            "user_" => SortBase::Reversed(User),
