use crate::cli::{Detail, Opts, Unit};
use crate::node::{Node, NodeType};
use crate::style::{styled, Seg};
use chrono::{DateTime, Local};
use colored::Colorize;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

type Cell = Vec<Seg>;

fn cell_width(cell: &Cell) -> usize {
    cell.iter().map(Seg::width).sum()
}

fn cell_rendered(cell: &Cell) -> String {
    cell.iter().map(|seg| seg.rendered.as_str()).collect()
}

fn pad_cell(cell: &Cell, width: usize, right_align: bool) -> String {
    let current = cell_width(cell);
    let rendered = cell_rendered(cell);
    if current >= width {
        return rendered;
    }
    let padding = " ".repeat(width - current);
    if right_align {
        format!("{padding}{rendered}")
    } else {
        format!("{rendered}{padding}")
    }
}

fn detail_title(detail: Detail) -> &'static str {
    match detail {
        Detail::Dev => "Device",
        Detail::Ino => "inode",
        Detail::Nlink => "Link#",
        Detail::Typ => "T",
        Detail::Perm => "Permissions",
        Detail::Oct => "SUGO",
        Detail::User => "User",
        Detail::Uid => "UID",
        Detail::Group => "Group",
        Detail::Gid => "GID",
        Detail::Size => "Size",
        Detail::Blocks => "Blocks",
        Detail::Btime => "Created",
        Detail::Ctime => "Changed",
        Detail::Mtime => "Modified",
        Detail::Atime => "Accessed",
        Detail::Git => "Git",
    }
}

fn detail_right_align(detail: Detail) -> bool {
    matches!(
        detail,
        Detail::Dev
            | Detail::Ino
            | Detail::Nlink
            | Detail::Oct
            | Detail::Uid
            | Detail::Gid
            | Detail::Size
            | Detail::Blocks
    )
}

fn plain_cell(text: impl Into<String>) -> Cell {
    vec![Seg::plain(text)]
}

fn format_size(size: u64, unit: Unit) -> (String, &'static str, usize) {
    // Returns (number, unit, unit field width).
    match unit {
        Unit::None => (size.to_string(), "B", 1),
        Unit::Binary => {
            const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
            let mut value = size as f64;
            let mut index = 0;
            while value >= 1024.0 && index < UNITS.len() - 1 {
                value /= 1024.0;
                index += 1;
            }
            (format!("{value:.1}"), UNITS[index], 3)
        }
        Unit::Decimal => {
            const UNITS: &[&str] = &["B", "kB", "MB", "GB", "TB", "PB", "EB"];
            let mut value = size as f64;
            let mut index = 0;
            while value >= 1000.0 && index < UNITS.len() - 1 {
                value /= 1000.0;
                index += 1;
            }
            (format!("{value:.1}"), UNITS[index], 2)
        }
    }
}

fn time_cell(time: Option<SystemTime>, detail: Detail) -> Cell {
    let Some(time) = time else {
        return Vec::new();
    };
    let local: DateTime<Local> = DateTime::from(time);
    let date = local.format("%Y-%b-%d").to_string();
    let clock = local.format("%I:%M%P").to_string();
    let date_seg = match detail {
        Detail::Btime => Seg::colored(date.clone(), date.as_str().bold().green()),
        Detail::Atime => Seg::colored(date.clone(), date.as_str().bold().blue()),
        _ => Seg::colored(date.clone(), date.as_str().bold().yellow()),
    };
    vec![date_seg, Seg::plain(" "), Seg::plain(clock)]
}

fn detail_cell(node: &Node, detail: Detail, opts: &Opts) -> Cell {
    match detail {
        Detail::Dev => plain_cell(node.dev().to_string()),
        Detail::Ino => plain_cell(node.ino().to_string()),
        Detail::Nlink => plain_cell(node.nlink().to_string()),
        Detail::Typ => {
            let text = node.typ.typ_char().to_string();
            let seg = match node.typ {
                NodeType::Dir => Seg::colored(text.clone(), text.as_str().blue()),
                NodeType::File => Seg::colored(text.clone(), text.as_str().dimmed()),
                _ => Seg::plain(text),
            };
            vec![seg]
        }
        Detail::Perm => {
            let mode = node.mode();
            let mut cell: Cell = Vec::new();
            // (read, write, execute, special bit, special lower, special upper)
            let triples = [
                (0o400, 0o200, 0o100, 0o4000, 's', 'S'),
                (0o040, 0o020, 0o010, 0o2000, 's', 'S'),
                (0o004, 0o002, 0o001, 0o1000, 't', 'T'),
            ];
            for (index, (read, write, exec, special, lower, upper)) in
                triples.iter().enumerate()
            {
                if index > 0 {
                    cell.push(Seg::plain(" "));
                }
                let read_char = if mode & read != 0 { "r" } else { "-" };
                cell.push(Seg::colored(
                    read_char,
                    if read_char == "r" {
                        read_char.yellow()
                    } else {
                        read_char.dimmed()
                    },
                ));
                let write_char = if mode & write != 0 { "w" } else { "-" };
                cell.push(Seg::colored(
                    write_char,
                    if write_char == "w" {
                        write_char.red()
                    } else {
                        write_char.dimmed()
                    },
                ));
                let exec_char = if mode & special != 0 {
                    if mode & exec != 0 {
                        lower.to_string()
                    } else {
                        upper.to_string()
                    }
                } else if mode & exec != 0 {
                    "x".to_owned()
                } else {
                    "-".to_owned()
                };
                let exec_seg = match exec_char.as_str() {
                    "x" => Seg::colored(exec_char.clone(), exec_char.as_str().green()),
                    "-" => Seg::colored(exec_char.clone(), exec_char.as_str().dimmed()),
                    _ => Seg::colored(exec_char.clone(), exec_char.as_str().magenta()),
                };
                cell.push(exec_seg);
            }
            cell
        }
        Detail::Oct => {
            let mode = node.mode();
            let special = (mode >> 9) & 0o7;
            let user = (mode >> 6) & 0o7;
            let group = (mode >> 3) & 0o7;
            let other = mode & 0o7;
            let special_seg = if special == 0 {
                Seg::plain(" ")
            } else {
                let text = special.to_string();
                Seg::colored(text.clone(), text.as_str().magenta())
            };
            let user_text = user.to_string();
            let group_text = group.to_string();
            let other_text = other.to_string();
            vec![
                special_seg,
                Seg::colored(user_text.clone(), user_text.as_str().blue()),
                Seg::colored(
                    group_text.clone(),
                    group_text.as_str().blue().dimmed(),
                ),
                Seg::colored(other_text.clone(), other_text.as_str().dimmed()),
            ]
        }
        Detail::User => vec![Seg::colored(
            node.user.clone(),
            node.user.as_str().bold().blue(),
        )],
        Detail::Uid => {
            let text = node.uid().to_string();
            vec![Seg::colored(text.clone(), text.as_str().bold().blue())]
        }
        Detail::Group => vec![Seg::colored(
            node.group.clone(),
            node.group.as_str().dimmed(),
        )],
        Detail::Gid => {
            let text = node.gid().to_string();
            vec![Seg::colored(text.clone(), text.as_str().dimmed())]
        }
        Detail::Size => {
            if node.typ == NodeType::Dir {
                Vec::new()
            } else {
                let (number, unit, unit_width) = format_size(node.size(), opts.unit);
                let spaces = 1 + unit_width.saturating_sub(unit.chars().count());
                vec![
                    Seg::colored(number.clone(), number.as_str().bold()),
                    Seg::plain(" ".repeat(spaces)),
                    Seg::colored(unit, unit.dimmed()),
                ]
            }
        }
        Detail::Blocks => {
            if node.typ == NodeType::Dir {
                Vec::new()
            } else {
                plain_cell(node.blocks().to_string())
            }
        }
        Detail::Btime => time_cell(node.btime(), detail),
        Detail::Ctime => time_cell(node.ctime(), detail),
        Detail::Mtime => time_cell(node.mtime(), detail),
        Detail::Atime => time_cell(node.atime(), detail),
        Detail::Git => Vec::new(),
    }
}

fn importance_words(node: &Node, opts: &Opts, for_icon: bool) -> Vec<String> {
    let difference = node.importance_difference(opts.imp);
    if difference < 0 {
        vec!["dimmed".to_owned()]
    } else if for_icon {
        Vec::new()
    } else if difference == 1 {
        vec!["italic".to_owned()]
    } else if difference >= 2 {
        vec!["underline".to_owned()]
    } else {
        Vec::new()
    }
}

fn node_style_hidden(node: &Node) -> bool {
    node.style.iter().any(|word| word == "hidden")
}

fn symlink_error_seg(error: &std::io::Error) -> Seg {
    let plain = format!("\u{f073a} error: {error}");
    // The reference renders this as a red icon, a bold-red "error:" and
    // a red message, with no reset between the icon and the label.
    let icon = format!("\u{f073a} ").red().to_string();
    let icon = icon
        .strip_suffix("\u{1b}[0m")
        .map(str::to_owned)
        .unwrap_or(icon);
    let rendered = format!(
        "{}{}{}",
        icon,
        "error:".bold().red(),
        format!(" {error}").red()
    );
    Seg {
        plain,
        rendered,
    }
}

fn append_symlink_targets(cell: &mut Cell, node: &Node) {
    let mut current: PathBuf = node.path.clone();
    loop {
        let Ok(target) = fs::read_link(&current) else {
            break;
        };
        let target_text = target.to_string_lossy().into_owned();
        let resolved = if target.is_absolute() {
            target.clone()
        } else {
            current
                .parent()
                .map(|parent: &Path| parent.join(&target))
                .unwrap_or_else(|| target.clone())
        };
        match fs::metadata(&resolved) {
            Ok(_) => {
                cell.push(Seg::plain(" "));
                cell.push(Seg::colored(
                    "\u{f0054}",
                    "\u{f0054}".magenta(),
                ));
                cell.push(Seg::plain(" "));
                let is_dir = fs::symlink_metadata(&resolved)
                    .map(|metadata| metadata.file_type().is_dir())
                    .unwrap_or(false);
                if is_dir {
                    cell.push(Seg::colored(
                        target_text.clone(),
                        target_text.as_str().blue(),
                    ));
                } else {
                    cell.push(Seg::plain(target_text));
                }
                current = resolved;
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                cell.push(Seg::plain(" "));
                cell.push(Seg::colored(
                    "\u{f17a3} ",
                    "\u{f17a3} ".red(),
                ));
                cell.push(Seg::colored(
                    target_text.clone(),
                    target_text.as_str().red().strikethrough(),
                ));
                break;
            }
            Err(error) if error.raw_os_error() == Some(libc::ELOOP) => {
                cell.push(Seg::plain(" "));
                cell.push(Seg::colored(
                    "\u{f0459} ",
                    "\u{f0459} ".yellow(),
                ));
                cell.push(Seg::colored(
                    target_text.clone(),
                    target_text.as_str().yellow(),
                ));
                break;
            }
            Err(error) => {
                cell.push(Seg::plain(" "));
                cell.push(symlink_error_seg(&error));
                break;
            }
        }
    }
}

pub fn name_cell(
    node: &Node,
    opts: &Opts,
    in_listing: bool,
    include_targets: bool,
    collapse_prefix: Option<&str>,
) -> Cell {
    let mut cell: Cell = Vec::new();
    if let Some(prefix) = collapse_prefix {
        if !prefix.is_empty() {
            cell.push(Seg::plain(prefix.to_owned()));
        }
    }

    if !node_style_hidden(node) {
        if opts.icon {
            let glyph = if node.icon.is_empty() {
                " ".to_owned()
            } else {
                node.icon.clone()
            };
            let mut words = node.style.clone();
            words.extend(importance_words(node, opts, true));
            cell.push(styled(format!("{glyph} "), &words));
        }

        let mut name_words = node.style.clone();
        name_words.extend(importance_words(node, opts, false));

        if in_listing && opts.align {
            if let Some(rest) = node.name.strip_prefix('.') {
                // The leading dot is always dimmed on its own.
                cell.push(styled(".", &["dimmed".to_owned()]));
                cell.push(styled(rest.to_owned(), &name_words));
            } else {
                cell.push(Seg::plain(" "));
                cell.push(styled(node.name.clone(), &name_words));
            }
        } else if in_listing {
            cell.push(styled(node.name.clone(), &name_words));
        } else {
            cell.push(styled(node.display_name.clone(), &name_words));
        }

        if opts.suffix {
            let suffix = node.typ.suffix();
            if !suffix.is_empty() {
                let mut words = node.style.clone();
                words.push("dimmed".to_owned());
                words.extend(importance_words(node, opts, false));
                cell.push(styled(suffix, &words));
            }
        }
    }

    if include_targets && opts.sym && node.typ == NodeType::Symlink {
        append_symlink_targets(&mut cell, node);
    }
    cell
}

pub struct Row<'a> {
    pub node: &'a Node,
    pub collapse_prefix: Option<String>,
}

pub fn render_table(rows: &[Row<'_>], opts: &Opts, in_listing: bool) -> String {
    let mut output = String::new();
    let has_details = !opts.details.is_empty();

    // Build all data cells first so column widths can be measured.
    let mut data: Vec<Vec<Cell>> = Vec::new();
    for row in rows {
        let mut cells: Vec<Cell> = Vec::new();
        for detail in &opts.details {
            cells.push(detail_cell(row.node, *detail, opts));
        }
        cells.push(name_cell(
            row.node,
            opts,
            in_listing,
            true,
            row.collapse_prefix.as_deref(),
        ));
        data.push(cells);
    }

    let column_count = opts.details.len() + 1;
    let mut widths = vec![0usize; column_count];
    if has_details && opts.header {
        for (index, detail) in opts.details.iter().enumerate() {
            widths[index] = detail_title(*detail).chars().count();
        }
        widths[column_count - 1] = "Name".len();
    }
    for cells in &data {
        for (index, cell) in cells.iter().enumerate() {
            widths[index] = widths[index].max(cell_width(cell));
        }
    }

    if has_details && opts.header {
        let mut header = String::new();
        for (index, detail) in opts.details.iter().enumerate() {
            let title = detail_title(*detail);
            let padded = if detail_right_align(*detail) {
                format!("{:>width$}", title, width = widths[index])
            } else {
                format!("{:<width$}", title, width = widths[index])
            };
            let text = format!("{padded} ");
            header.push_str(
                &text
                    .as_str()
                    .bold()
                    .italic()
                    .underline()
                    .to_string(),
            );
        }
        header.push_str(&"Name".bold().italic().underline().to_string());
        output.push_str(&header);
        output.push('\n');
    }

    for cells in &data {
        let mut line = String::new();
        for (index, cell) in cells.iter().enumerate() {
            if index > 0 {
                line.push(' ');
            }
            if index + 1 == cells.len() {
                line.push_str(&cell_rendered(cell));
            } else {
                let detail = opts.details[index];
                line.push_str(&pad_cell(
                    cell,
                    widths[index],
                    detail_right_align(detail),
                ));
            }
        }
        output.push_str(&line);
        output.push('\n');
    }
    output
}

fn stdout_terminal_width() -> Option<usize> {
    let mut winsize: libc::winsize = unsafe { std::mem::zeroed() };
    let result = unsafe {
        libc::ioctl(
            libc::STDOUT_FILENO,
            libc::TIOCGWINSZ,
            &mut winsize,
        )
    };
    if result != 0 || winsize.ws_col == 0 || winsize.ws_row == 0 {
        return None;
    }
    Some(winsize.ws_col as usize)
}

pub fn render_grid(nodes: &[Node], opts: &Opts, in_listing: bool) -> String {
    if nodes.is_empty() {
        return String::new();
    }
    let cells: Vec<Cell> = nodes
        .iter()
        .map(|node| name_cell(node, opts, in_listing, false, None))
        .collect();
    let max_width = cells.iter().map(|cell| cell_width(cell)).max().unwrap_or(0);
    let max_columns = match stdout_terminal_width() {
        Some(width) => ((width + 2) / (max_width + 2)).max(1),
        None => 1,
    };
    if max_columns <= 1 {
        let mut output = String::new();
        for cell in &cells {
            output.push_str(&cell_rendered(cell));
            output.push('\n');
        }
        return output;
    }
    let count = cells.len();
    let row_count = count.div_ceil(max_columns);
    let column_count = count.div_ceil(row_count);

    let mut output = String::new();
    for row in 0..row_count {
        let mut line = String::new();
        for column in 0..column_count {
            let index = if opts.down {
                column * row_count + row
            } else {
                row * column_count + column
            };
            if index >= count {
                break;
            }
            if column > 0 {
                line.push_str("  ");
            }
            line.push_str(&pad_cell(&cells[index], max_width, false));
        }
        output.push_str(&line);
        output.push('\n');
    }
    output
}

/// Build the flattened, depth-first list of rows for the collapsed tree
/// view of one directory listing.
pub fn collapse_rows<'a>(nodes: &'a [Node], opts: &Opts) -> Vec<Row<'a>> {
    if !opts.collapse {
        return nodes
            .iter()
            .map(|node| Row {
                node,
                collapse_prefix: None,
            })
            .collect();
    }

    let name_to_index: HashMap<&str, usize> = nodes
        .iter()
        .enumerate()
        .map(|(index, node)| (node.name.as_str(), index))
        .collect();

    let parents: Vec<Option<usize>> = nodes
        .iter()
        .map(|node| match &node.collapse {
            None => None,
            Some(crate::config::Collapse::Name(principal)) => {
                name_to_index.get(principal.as_str()).copied()
            }
            Some(crate::config::Collapse::Ext(extension)) => {
                let principal = Path::new(&node.name)
                    .with_extension(extension)
                    .to_string_lossy()
                    .into_owned();
                name_to_index.get(principal.as_str()).copied()
            }
        })
        .collect();

    let enters_cycle = |start: usize| -> bool {
        let mut seen = vec![false; nodes.len()];
        let mut current = start;
        loop {
            if seen[current] {
                return true;
            }
            seen[current] = true;
            match parents[current] {
                Some(parent) => current = parent,
                None => return false,
            }
        }
    };

    let effective_parents: Vec<Option<usize>> = parents
        .iter()
        .enumerate()
        .map(|(index, parent)| {
            if parent.is_some() && !enters_cycle(index) {
                *parent
            } else {
                None
            }
        })
        .collect();

    let mut children: Vec<Vec<usize>> = vec![Vec::new(); nodes.len()];
    for (index, parent) in effective_parents.iter().enumerate() {
        if let Some(parent) = parent {
            children[*parent].push(index);
        }
    }

    let leading = if opts.align { 3 } else { 2 };
    let chunk_width = leading + 3;

    fn visit<'a>(
        index: usize,
        nodes: &'a [Node],
        children: &[Vec<usize>],
        ancestor_last: &[bool],
        is_last: bool,
        depth: usize,
        leading: usize,
        chunk_width: usize,
        rows: &mut Vec<Row<'a>>,
    ) {
        let prefix = if depth == 0 {
            None
        } else {
            let mut prefix = String::new();
            for &last in ancestor_last {
                if last {
                    prefix.push_str(&" ".repeat(chunk_width));
                } else {
                    prefix.push_str(&" ".repeat(leading));
                    prefix.push('│');
                    prefix.push_str(&" ".repeat(chunk_width - leading - 1));
                }
            }
            prefix.push_str(&" ".repeat(leading));
            prefix.push_str(if is_last { "└─ " } else { "├─ " });
            Some(prefix)
        };
        rows.push(Row {
            node: &nodes[index],
            collapse_prefix: prefix,
        });
        let child_count = children[index].len();
        for (position, &child) in children[index].iter().enumerate() {
            let child_is_last = position + 1 == child_count;
            let mut child_ancestors = ancestor_last.to_vec();
            if depth > 0 {
                child_ancestors.push(is_last);
            }
            visit(
                child,
                nodes,
                children,
                &child_ancestors,
                child_is_last,
                depth + 1,
                leading,
                chunk_width,
                rows,
            );
        }
    }

    let mut rows = Vec::new();
    for (index, parent) in effective_parents.iter().enumerate() {
        if parent.is_none() {
            visit(
                index,
                nodes,
                &children,
                &[],
                true,
                0,
                leading,
                chunk_width,
                &mut rows,
            );
        }
    }
    rows
}
