mod cli;
mod config;
mod node;
mod render;
mod style;

use cli::{Opts, SortBase, SortField};
use colored::Colorize;
use node::{create_child_node, create_root_node, Node, NodeType};
use render::{collapse_rows, render_grid, render_table, Row};
use std::cmp::Ordering;
use std::fs;
use std::path::PathBuf;
use std::time::SystemTime;
use style::error_line;

fn compare_times(a: Option<SystemTime>, b: Option<SystemTime>) -> Ordering {
    match (a, b) {
        (Some(a), Some(b)) => a.cmp(&b),
        _ => Ordering::Equal,
    }
}

fn compare_nodes(a: &Node, b: &Node, base: SortBase) -> Ordering {
    let (field, reversed) = match base {
        SortBase::Forward(field) => (field, false),
        SortBase::Reversed(field) => (field, true),
        SortBase::InodeReversed | SortBase::NlinksReversed => {
            unreachable!("src/enums/sort_fields.rs / impl SortField / cmp_time")
        }
    };
    let ordering = match field {
        SortField::Dev => a.dev().cmp(&b.dev()),
        SortField::Ino => a.ino().cmp(&b.ino()),
        SortField::Nlink => a.nlink().cmp(&b.nlink()),
        SortField::Typ => a.typ.sort_rank().cmp(&b.typ.sort_rank()),
        SortField::Cat => (a.typ != NodeType::Dir).cmp(&(b.typ != NodeType::Dir)),
        SortField::User => a.user.cmp(&b.user),
        SortField::Uid => a.uid().cmp(&b.uid()),
        SortField::Group => a.group.cmp(&b.group),
        SortField::Gid => a.gid().cmp(&b.gid()),
        SortField::Size => a.size().cmp(&b.size()),
        SortField::Blocks => a.blocks().cmp(&b.blocks()),
        SortField::Btime => compare_times(a.btime(), b.btime()),
        SortField::Ctime => compare_times(a.ctime(), b.ctime()),
        SortField::Mtime => compare_times(a.mtime(), b.mtime()),
        SortField::Atime => compare_times(a.atime(), b.atime()),
        SortField::Name => a.name.cmp(&b.name),
        SortField::Cname => a.canonical_name().cmp(&b.canonical_name()),
        SortField::Ext => a.extension().cmp(&b.extension()),
    };
    if reversed {
        ordering.reverse()
    } else {
        ordering
    }
}

fn sort_nodes(nodes: &mut [Node], opts: &Opts) {
    for base in opts.sort_bases.iter().rev() {
        nodes.sort_by(|a, b| compare_nodes(a, b, *base));
    }
}

fn keeps(node: &Node, opts: &Opts) -> bool {
    if !opts
        .types
        .iter()
        .any(|typ| typ == node.typ.filter_name())
    {
        return false;
    }
    if let Some(only) = &opts.only {
        if !only.is_match(&node.name_bytes) {
            return false;
        }
    }
    if let Some(exclude) = &opts.exclude {
        if exclude.is_match(&node.name_bytes) {
            return false;
        }
    }
    if node.importance_difference(opts.imp) <= -2 {
        return false;
    }
    true
}

fn print_group(nodes: &[Node], opts: &Opts, in_listing: bool, may_collapse: bool) {
    if opts.details.is_empty() && opts.grid {
        print!("{}", render_grid(nodes, opts, in_listing));
        return;
    }
    if may_collapse {
        let rows = collapse_rows(nodes, opts);
        print!("{}", render_table(&rows, opts, in_listing));
    } else {
        let rows: Vec<Row<'_>> = nodes
            .iter()
            .map(|node| Row {
                node,
                collapse_prefix: None,
            })
            .collect();
        print!("{}", render_table(&rows, opts, in_listing));
    }
}

fn main() {
    let opts = Opts::parse();
    let path_count = opts.paths.len();

    let mut errors: Vec<(PathBuf, String)> = Vec::new();
    let mut files: Vec<Node> = Vec::new();
    let mut dirs: Vec<Node> = Vec::new();

    for path in &opts.paths {
        match create_root_node(path.clone()) {
            Ok(node) => {
                if node.typ == NodeType::Dir {
                    dirs.push(node);
                } else {
                    files.push(node);
                }
            }
            Err(error) => errors.push((path.clone(), error)),
        }
    }

    for (path, error) in &errors {
        println!("{}:", path.display().to_string().bold());
        println!("\t{}", error_line(error));
    }

    if !files.is_empty() {
        print_group(&files, &opts, false, false);
    }

    for dir in &dirs {
        if path_count > 1 {
            println!("\n{}", format!("{}:", dir.path.display()).bold());
        }
        match fs::read_dir(&dir.path) {
            Err(error) => {
                println!("{}", error_line(&error.to_string()));
            }
            Ok(entries) => {
                let mut nodes: Vec<Node> = Vec::new();
                for entry in entries {
                    let Ok(entry) = entry else { continue };
                    let Some(node) = create_child_node(entry.path(), &dir.config) else {
                        continue;
                    };
                    if keeps(&node, &opts) {
                        nodes.push(node);
                    }
                }
                sort_nodes(&mut nodes, &opts);
                print_group(&nodes, &opts, true, true);
            }
        }
    }
}
