        SortField::Cname => a.canonical_name().cmp(&b.canonical_name()),
        SortField::Ext => a.extension().cmp(&b.extension()),
    };
    if reversed {
        ordering.reverse()
    } else {
        ordering
    }
}

fn sort_nodes(nodes: &mut [Node], opts: &Opts) {
    for base in opts.sort_bases.iter().rev() {
        nodes.sort_by(|a, b| compare_nodes(a, b, *base));
    }
}

fn keeps(node: &Node, opts: &Opts) -> bool {
    if !opts
        .types
        .iter()
        .any(|typ| typ == node.typ.filter_name())
    {
        return false;
    }
    if let Some(only) = &opts.only {
        if !only.is_match(&node.name_bytes) {
            return false;
        }
    }
    if let Some(exclude) = &opts.exclude {
        if exclude.is_match(&node.name_bytes) {
            return false;
        }
    }
    if node.importance_difference(opts.imp) <= -2 {
        return false;
    }
    true
}

fn print_group(nodes: &[Node], opts: &Opts, in_listing: bool, may_collapse: bool) {
    if opts.details.is_empty() && opts.grid {
        print!("{}", render_grid(nodes, opts, in_listing));
        return;
    }
    if may_collapse {
        let rows = collapse_rows(nodes, opts);
        print!("{}", render_table(&rows, opts, in_listing));
    } else {
        let rows: Vec<Row<'_>> = nodes
            .iter()
            .map(|node| Row {
                node,
                collapse_prefix: None,
            })
            .collect();
        print!("{}", render_table(&rows, opts, in_listing));
    }
}

fn main() {
    let opts = Opts::parse();
    let path_count = opts.paths.len();

    let mut errors: Vec<(PathBuf, String)> = Vec::new();
    let mut files: Vec<Node> = Vec::new();
    let mut dirs: Vec<Node> = Vec::new();

    for path in &opts.paths {
        match create_root_node(path.clone()) {
            Ok(node) => {
                if node.typ == NodeType::Dir {
                    dirs.push(node);
                } else {
                    files.push(node);
                }
            }
            Err(error) => errors.push((path.clone(), error)),
        }
    }

    for (path, error) in &errors {
        println!("{}:", path.display().to_string().bold());
        println!("\t{}", error_line(error));
    }

    if !files.is_empty() {
        print_group(&files, &opts, false, false);
    }

    for dir in &dirs {
        if path_count > 1 {
            println!("\n{}", format!("{}:", dir.path.display()).bold());
        }
        match fs::read_dir(&dir.path) {
            Err(error) => {
                println!("{}", error_line(&error.to_string()));
            }
            Ok(entries) => {
                let mut nodes: Vec<Node> = Vec::new();
                for entry in entries {
                    let Ok(entry) = entry else { continue };
                    let Some(node) = create_child_node(entry.path(), &dir.config) else {
                        continue;
                    };
                    if keeps(&node, &opts) {
                        nodes.push(node);
                    }
                }
                sort_nodes(&mut nodes, &opts);
                print_group(&nodes, &opts, true, true);
            }
        }
    }
}
