p += '''

fn parse_color(word: &str) -> Option<Color> {
    // The names recognised here are those observed from the reference
    // program's handling of `style` strings in configuration files:
    // the basic and bright colour names (in snake_case), `rgb(r,g,b)`
    // triples, and the hexadecimal forms understood by `colored`.
    let color = match word {
        "black" => Color::Black,
        "red" => Color::Red,
        "green" => Color::Green,
        "yellow" => Color::Yellow,
        "blue" => Color::Blue,
        "magenta" | "purple" => Color::Magenta,
        "cyan" => Color::Cyan,
        "white" => Color::White,
        "bright_black" => Color::BrightBlack,
        "bright_red" => Color::BrightRed,
        "bright_green" => Color::BrightGreen,
        "bright_yellow" => Color::BrightYellow,
        "bright_blue" => Color::BrightBlue,
        "bright_magenta" => Color::BrightMagenta,
        "bright_cyan" => Color::BrightCyan,
        "bright_white" => Color::BrightWhite,
        _ => {
            if let Some(inner) = word
                .strip_prefix("rgb(")
                .and_then(|rest| rest.strip_suffix(')'))
            {
                let mut parts = inner.split(',');
                let red: u8 = parts.next()?.parse().ok()?;
                let green: u8 = parts.next()?.parse().ok()?;
                let blue: u8 = parts.next()?.parse().ok()?;
                if parts.next().is_some() {
                    return None;
                }
                return Some(Color::TrueColor {
                    r: red,
                    g: green,
                    b: blue,
                });
            }
            return word.parse::<Color>().ok();
        }
    };
    Some(color)
}
