pub fn build_tree<'a>(nodes: &'a [Node], collapse_enabled: bool) -> Vec<TreeNode<'a>> {
    if !collapse_enabled {
        return nodes
            .iter()
            .map(|node| TreeNode {
                node,
                children: Vec::new(),
            })
            .collect();
    }

    let name_to_index: HashMap<&str, usize> = nodes
        .iter()
        .enumerate()
        .map(|(index, node)| (node.name.as_str(), index))
        .collect();

    let parents: Vec<Option<usize>> = nodes
        .iter()
        .map(|node| match &node.collapse {
            None => None,
            Some(crate::config::Collapse::Name(principal)) => {
                name_to_index.get(principal.as_str()).copied()
            }
            Some(crate::config::Collapse::Ext(extension)) => {
                let principal = Path::new(&node.name)
                    .with_extension(extension)
                    .to_string_lossy()
                    .into_owned();
                name_to_index.get(principal.as_str()).copied()
            }
        })
        .collect();

    let enters_cycle = |start: usize| -> bool {
        let mut seen = vec![false; nodes.len()];
        let mut current = start;
        loop {
            if seen[current] {
                return true;
            }
            seen[current] = true;
            match parents[current] {
                Some(parent) => current = parent,
                None => return false,
            }
        }
    };

    let effective_parents: Vec<Option<usize>> = parents
        .iter()
        .enumerate()
        .map(|(index, parent)| {
            if parent.is_some() && !enters_cycle(index) {
                *parent
            } else {
                None
            }
        })
        .collect();

    fn build<'a>(
        index: usize,
        nodes: &'a [Node],
        children_of: &[Vec<usize>],
    ) -> TreeNode<'a> {
        TreeNode {
            node: &nodes[index],
            children: children_of[index]
                .iter()
                .map(|&child| build(child, nodes, children_of))
                .collect(),
        }
    }

    let mut children_of: Vec<Vec<usize>> = vec![Vec::new(); nodes.len()];
    for (index, parent) in effective_parents.iter().enumerate() {
        if let Some(parent) = parent {
            children_of[*parent].push(index);
        }
    }
    effective_parents
        .iter()
        .enumerate()
        .filter(|(_, parent)| parent.is_none())
        .map(|(index, _)| build(index, nodes, &children_of))
        .collect()
}

/// Flatten a (sorted) tree into table rows, computing the branch-drawing
/// prefix for each row.
pub fn flatten_tree<'a>(tree: &[TreeNode<'a>], opts: &Opts) -> Vec<Row<'a>> {
    let leading = if opts.align { 3 } else { 2 };
    let chunk_width = leading + 3;

    fn visit<'a>(
        item: &TreeNode<'a>,
        ancestor_last: &[bool],
        is_last: bool,
        depth: usize,
        leading: usize,
        chunk_width: usize,
        rows: &mut Vec<Row<'a>>,
    ) {
        let prefix = if depth == 0 {
            None
        } else {
            let mut prefix = String::new();
            for &last in ancestor_last {
                if last {
                    prefix.push_str(&" ".repeat(chunk_width));
                } else {
                    prefix.push_str(&" ".repeat(leading));
                    prefix.push('│');
                    prefix.push_str(&" ".repeat(chunk_width - leading - 1));
                }
            }
            prefix.push_str(&" ".repeat(leading));
            prefix.push_str(if is_last { "└─ " } else { "├─ " });
            Some(prefix)
        };
        rows.push(Row {
            node: item.node,
            collapse_prefix: prefix,
        });
        let child_count = item.children.len();
        for (position, child) in item.children.iter().enumerate() {
            let child_is_last = position + 1 == child_count;
            let mut child_ancestors = ancestor_last.to_vec();
            if depth > 0 {
                child_ancestors.push(is_last);
            }
            visit(
                child,
                &child_ancestors,
                child_is_last,
                depth + 1,
                leading,
                chunk_width,
                rows,
            );
        }
    }

    let mut rows = Vec::new();
    for item in tree {
        visit(item, &[], true, 0, leading, chunk_width, &mut rows);
    }
    rows
}
