{"command":"cat > /tmp/probe_icon_keys_batch.py << 'PY'
import subprocess, os, shutil, re
# Candidate generation from text in the local Python library and file
# names found on the system.  This is just a source of English/tech
# words to try as possible icon-map keys.
words=set()
for root in ["/usr/lib/python3.10","/usr/share/doc"]:
 for dirpath,dirs,files in os.walk(root):
  for f in files:
   if f.endswith(('.py','.txt','.md','.rst')):
    try: text=open(os.path.join(dirpath,f),encoding='utf-8',errors='ignore').read()
    except: continue
    for w in re.findall(r'[A-Za-z][A-Za-z_]{1,25}', text):
        for part in w.lower().split('_'):
            if 2<=len(part)<=20: words.add(part)
        if '_' in w and len(w)<=25: words.add(w.lower())
print('candidates',len(words))
words=sorted(words)
found=[]
for start in range(0,len(words),400):
 batch=words[start:start+400]
 d="/tmp/tkeybatch"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
 specs=[]
 for i,w in enumerate(batch):
  name=f"p{i:03d}"
  open(os.path.join(d,name),"w").write("x")
  specs.append(f"  - pattern: '^{name}$'\n    icons: ['{w}']")
 open(os.path.join(d,".pls.yml"),"w").write("specs:\n"+"\n".join(specs)+"\n")
 r=subprocess.run(["/workspace/executable","-a=false","-s=name","-c=false"],cwd=d,capture_output=True,text=True,env={**os.environ,"HOME":"/tmp/nohome"})
 if r.returncode!=0 or b"error" in r.stdout:
  print("batch error",start,r.stdout[:200]); continue
 for line in r.stdout.splitlines():
  if not line.startswith("  "):
   # name at end; icon is first token(s) before final name
   # strip name pNNN
   m=re.search(r'\bp(\d{3})$',line)
   if m:
    w=batch[int(m.group(1))]; found.append((w,line))
print('found',found)
PY
timeout 1200 python3 /tmp/probe_icon_keys_batch.py > /tmp/iconkeys.txt 2>&1; tail -n 20 /tmp/iconkeys.txt"}

