{"command":"python3 - << 'PY'
p=open("src/render.rs").read()
p=p.replace("use chrono::{DateTime, Local};", "use chrono::{DateTime, FixedOffset, Utc};")
old='''    let local: DateTime<Local> = DateTime::from(time);'''
new='''    // The reference converts every timestamp with the UTC offset in
    // force *now*, rather than with the offset historically in force
    // at the timestamp itself.
    let offset = FixedOffset::east_opt(current_local_offset_seconds())
        .unwrap_or_else(|| FixedOffset::east_opt(0).expect("zero offset is valid"));
    let local = DateTime::<Utc>::from(time).with_timezone(&offset);'''
assert old in p
p=p.replace(old,new)
p += '''

fn current_local_offset_seconds() -> i32 {
    unsafe {
        libc::tzset();
        let mut now: libc::time_t = 0;
        libc::time(&mut now);
        let mut tm: libc::tm = std::mem::zeroed();
        let result = libc::localtime_r(&now, &mut tm);
        if result.is_null() {
            0
        } else {
            tm.tm_gmtoff as i32
        }
    }
}
'''
open("src/render.rs","w").write(p)
