{"command":"cat > /tmp/rewrite_tree.py << 'PY'
p=open("src/render.rs").read()
start=p.index("/// Build a tree from a directory listing")
end=p.index("/// Flatten a (sorted) tree")
new=r'''/// Build a tree from a directory listing, in the order the entries were
/// read.  Sorting is applied to the tree afterwards (see `sort_tree` in
/// the caller).
pub fn build_tree<'a>(nodes: &'a [Node], collapse_enabled: bool) -> Vec<TreeNode<'a>> {
    if !collapse_enabled {
        return nodes
            .iter()
            .map(|node| TreeNode {
                node,
                children: Vec::new(),
            })
            .collect();
    }

    fn principal_name(node: &Node) -> Option<String> {
        match &node.collapse {
            None => None,
            Some(crate::config::Collapse::Name(principal)) => Some(principal.clone()),
            Some(crate::config::Collapse::Ext(extension)) => {
                // The principal is the node whose name is this node's
                // file stem with the given extension.  This is built as
                // a plain string (rather than with `with_extension`),
                // so an extension containing a separator simply fails
                // to match any node.
                let stem = Path::new(&node.name)
                    .file_stem()
                    .map(|stem| stem.to_string_lossy().into_owned())
                    .unwrap_or_else(|| node.name.clone());
                if extension.is_empty() {
                    Some(stem)
                } else {
                    Some(format!("{stem}.{extension}"))
                }
            }
        }
    }

    // Partition into principal nodes (those with no collapse target of
    // their own) and dependents grouped by their principal's name.
    let mut principal_indices: Vec<usize> = Vec::new();
    let mut dependents: HashMap<String, Vec<usize>> = HashMap::new();
    for (index, node) in nodes.iter().enumerate() {
        match principal_name(node) {
            None => principal_indices.push(index),
            Some(principal) => dependents.entry(principal).or_default().push(index),
        }
    }

    fn attach<'a>(
        index: usize,
        nodes: &'a [Node],
        dependents: &mut HashMap<String, Vec<usize>>,
    ) -> TreeNode<'a> {
        let child_indices = dependents
            .remove(nodes[index].name.as_str())
            .unwrap_or_default();
        TreeNode {
            node: &nodes[index],
            children: child_indices
                .into_iter()
                .map(|child| attach(child, nodes, dependents))
                .collect(),
        }
    }

    let mut forest: Vec<TreeNode<'a>> = principal_indices
        .iter()
        .map(|&index| attach(index, nodes, &mut dependents))
        .collect();
    // Anything left in the map could not be reached from a principal:
    // its principal is absent, or its chain of principals loops back on
    // itself.  Such nodes stand as roots of their own, after the
    // ordinary roots.
    for residual in dependents.into_values() {
        for index in residual {
            forest.push(TreeNode {
                node: &nodes[index],
                children: Vec::new(),
            });
        }
    }
    forest
}

'''
