{"command":"python3 - << 'PY'
p=open("src/render.rs").read()
p=p.replace("use chrono::{DateTime, FixedOffset, Utc};","use chrono::{DateTime, Utc};")
old='''    let offset = FixedOffset::east_opt(current_local_offset_seconds())
        .unwrap_or_else(|| FixedOffset::east_opt(0).expect("zero offset is valid"));
    let local = DateTime::<Utc>::from(time).with_timezone(&offset);'''
new='''    // Shift the UTC instant by that offset and format it as UTC; this
    // also copes with the \\u{00b1}24h offsets the C library can report,
    // which a fixed-offset type may not be able to represent.
    let offset_seconds = current_local_offset_seconds() as i64;
    let utc = DateTime::<Utc>::from(time);
    let local = if offset_seconds >= 0 {
        utc + chrono::TimeDelta::seconds(offset_seconds)
    } else {
        utc - chrono::TimeDelta::seconds(-offset_seconds)
    };'''
assert old in p; p=p.replace(old,new); open("src/render.rs","w").write(p)
PY
